update public.learning_paths
set
  title = 'Ethics in Criminal Justice',
  goal = 'Ethics in Criminal Justice',
  summary = 'Ethics in Criminal Justice teaches the ethical vocabulary needed to analyze decisions across policing, courts, corrections, research, and policy when legal permission and moral justification diverge. Students examine legitimacy and procedural justice, police discretion and use of force, surveillance and privacy, bias and equal protection, misconduct and accountability, investigative and forensic integrity, prosecutorial and defense duties, judicial and pretrial ethics, correctional dignity, punishment theory, victims and restorative justice, data and algorithmic risk, and ethical leadership.',
  data = $ecjjson${"slug": "ethics-in-criminal-justice", "title": "Ethics in Criminal Justice", "description": "Ethics in Criminal Justice teaches the ethical vocabulary needed to analyze decisions across policing, courts, corrections, research, and policy when legal permission and moral justification diverge. Students examine legitimacy and procedural justice, police discretion and use of force, surveillance and privacy, bias and equal protection, misconduct and accountability, investigative and forensic integrity, prosecutorial and defense duties, judicial and pretrial ethics, correctional dignity, punishment theory, victims and restorative justice, data and algorithmic risk, and ethical leadership.", "topics": [{"id": "19671742-5b0e-46d7-8849-a897c0575468", "type": "topic", "title": "Foundations of Criminal Justice Ethics: Moral Theory, Law, Discretion, and Power", "description": "Students learn the ethical vocabulary needed to analyze decisions across policing, courts, corrections, research, and policy, especially when legal permission and moral justification diverge.", "children": [{"id": "33a23b0e-aefe-4d55-9581-2d88921a8dde", "type": "subtopic", "title": "Ethical theories", "children": [{"id": "98b1e2dc-efaf-466a-a34d-d5f0fa75e2a1", "type": "concept", "title": "Consequentialism, deontology, virtue ethics, care ethics, rights theory, justice theory, and moral pluralism"}, {"id": "c7e53f7e-1e91-4259-8afb-0689652b7f40", "type": "concept", "title": "Ends, means, duties, character, relationships, fairness, and dignity"}, {"id": "c024f084-481f-4811-98ec-8af8287722ab", "type": "concept", "title": "Using theory without turning real cases into abstractions"}], "description": "Students learn frameworks for disciplined moral reasoning."}, {"id": "8146cbf1-9291-437f-87bf-5b04a81da989", "type": "subtopic", "title": "Law versus ethics", "children": [{"id": "1d0bf60d-4c89-4333-9f75-2e50c14ab241", "type": "concept", "title": "Constitutional minimums, professional standards, policy, culture, and conscience"}, {"id": "8e7a5cfa-578a-41db-97b8-6f06ef377ed3", "type": "concept", "title": "Legal authority, moral authority, and legitimacy"}, {"id": "29294cc0-de61-4a4b-9e21-df39136c7a72", "type": "concept", "title": "Discretion in low-visibility and high-pressure settings"}], "description": "The point is to understand that lawful conduct may still be unethical and ethical conduct may require more than compliance."}, {"id": "d08e1810-98c1-4636-a528-1fabec8fd585", "type": "subtopic", "title": "Power and vulnerability", "children": [{"id": "21923fd2-776a-466e-ab2c-b44aaaab75da", "type": "concept", "title": "Coercion, custody, surveillance, force, prosecution, punishment, and supervision"}, {"id": "fab587ee-8ba5-4067-9dca-2032b5d3cf24", "type": "concept", "title": "Vulnerable people, trauma, poverty, disability, youth, immigration status, and mental illness"}, {"id": "20104b15-457f-45ca-9dd9-baaf8e9d4567", "type": "concept", "title": "Public trust, abuse of authority, and professional humility"}], "description": "Students analyze how state power changes ethical duties."}]}, {"id": "d17de456-6c09-432e-814f-72514790b444", "type": "topic", "title": "Rule of Law, Legitimacy, Public Trust, and Procedural Justice", "description": "This module explains why criminal justice legitimacy depends not only on outcomes but also on fairness, dignity, voice, neutrality, transparency, and trustworthy motives.", "children": [{"id": "2d3ae9ae-1400-4638-8a55-bf8c5805b7e0", "type": "subtopic", "title": "Rule-of-law values", "children": [{"id": "ad28f141-1f32-437f-a247-753e2479cd27", "type": "concept", "title": "Equality before law, notice, neutrality, accountability, due process, transparency, and constraint on arbitrary power"}, {"id": "988c4940-ee34-4964-ac21-ddcaede64042", "type": "concept", "title": "Discretion bounded by reasons and evidence"}, {"id": "05eb6e24-670f-4b49-84d9-a58c2ce76a63", "type": "concept", "title": "Lawful authority versus legitimate authority"}], "description": "Students learn the ethical foundations of a legal system that deserves obedience."}, {"id": "70c3a7ac-8e79-403c-9a14-61085991847b", "type": "subtopic", "title": "Procedural justice", "children": [{"id": "7b4997a4-26e0-40aa-bfc6-2a18b92122fa", "type": "concept", "title": "Voice, neutrality, respectful treatment, trustworthy motives, and explanation"}, {"id": "4b4464c6-3b34-4faa-886d-1f3ef5267aed", "type": "concept", "title": "Officer, prosecutor, court, and correctional encounters"}, {"id": "255bb211-7eb0-40fc-8323-0604c9e829e8", "type": "concept", "title": "Compliance, cooperation, legitimacy, and community trust"}], "description": "The gist is that people judge justice systems by process as well as outcomes."}, {"id": "68f3e134-e8fa-4823-bf5c-9c1075a10658", "type": "subtopic", "title": "Trust repair", "children": [{"id": "25723d87-92bd-4b5c-a4be-15b08b6cf10a", "type": "concept", "title": "Apology, transparency, discipline, policy change, data disclosure, and community participation"}, {"id": "7c6517b4-6e4b-4ba5-b27f-dc324176e64e", "type": "concept", "title": "Internal affairs, civilian oversight, consent decrees, and reform monitoring"}, {"id": "1315bdd6-4f55-43ec-8f95-900dba992f72", "type": "concept", "title": "Limits of symbolic reform without structural change"}], "description": "Students study how institutions recover credibility after harm."}]}, {"id": "5b07b225-fb28-4ea6-be41-839bbe15bd94", "type": "topic", "title": "Police Ethics, Discretion, Use of Force, and Duty to Intervene", "description": "Students examine ethical judgment in encounters where officers hold coercive power, face risk, and must balance safety, rights, restraint, and public accountability.", "children": [{"id": "257fa908-8405-421d-9416-c4f034d95cf8", "type": "subtopic", "title": "Discretion in policing", "children": [{"id": "de42b107-766e-4894-9f30-f96bfdb60d05", "type": "concept", "title": "Stops, warnings, arrests, citations, searches, referrals, and de-escalation"}, {"id": "1c937af5-a535-4104-b3af-acfb286daf9d", "type": "concept", "title": "Low-level offenses, nuisance enforcement, mental health calls, and homelessness"}, {"id": "3cc4b8f3-a492-451b-8476-fead790849df", "type": "concept", "title": "Officer safety, community safety, and proportionality"}], "description": "Students learn why ordinary encounters carry ethical weight."}, {"id": "9eb61682-9475-454e-87b3-a365e8f5c0d5", "type": "subtopic", "title": "Use of force", "children": [{"id": "f10d373d-bc7a-4bbf-92d1-28a857d82c1e", "type": "concept", "title": "Graham reasonableness, de-escalation, less-lethal options, deadly force, positional asphyxia, pursuits, and crowd control"}, {"id": "bf2def3b-da2d-4268-b435-23aa864a08f9", "type": "concept", "title": "Policy, training, reporting, review boards, and body-worn camera evidence"}, {"id": "046dceae-6d46-47c5-9cce-55ecc2c04a5d", "type": "concept", "title": "After-action review, trauma, and community impact"}], "description": "The point is to analyze necessity, proportionality, restraint, and accountability."}, {"id": "234f2b8c-3f60-4025-8cc5-3f7fbe1da13a", "type": "subtopic", "title": "Duty to intervene", "children": [{"id": "2f895145-fa06-46de-b6f3-610527b891d4", "type": "concept", "title": "Bystander intervention, reporting, anti-retaliation, supervisor responsibility, and early intervention systems"}, {"id": "b7e4c2e4-797d-4567-a2aa-104896ab4bd6", "type": "concept", "title": "Loyalty, code of silence, courage, and moral injury"}, {"id": "f522465d-2913-483a-8175-87fd77a61a38", "type": "concept", "title": "Training, culture, and leadership reinforcement"}], "description": "Students learn that ethical policing includes preventing peer misconduct."}]}, {"id": "1106bd3c-b8cd-43b3-99e2-b3e410abb056", "type": "topic", "title": "Stops, Searches, Surveillance, Privacy, and Digital Policing", "description": "This topic applies ethical reasoning to investigative powers, privacy, consent, data collection, surveillance technologies, and constitutional limits.", "children": [{"id": "a6522600-c30a-4c0d-928d-f7a46ae83da5", "type": "subtopic", "title": "Investigative powers", "children": [{"id": "577302f7-4772-405c-ba08-1d4b833e5f27", "type": "concept", "title": "Stops, frisks, consent searches, warrants, exigency, plain view, and inventory searches"}, {"id": "d43c0d45-cc74-4c7b-94cd-1db67eb396b4", "type": "concept", "title": "Reasonable suspicion, probable cause, pretext, and discretionary enforcement"}, {"id": "b02e7bdb-281c-4e99-97db-3beb342aa304", "type": "concept", "title": "Respectful communication and dignity during searches"}], "description": "Students connect constitutional doctrine to ethical restraint."}, {"id": "33fe742c-d8a9-4303-a847-5165866b09c1", "type": "subtopic", "title": "Surveillance ethics", "children": [{"id": "37250192-5969-42aa-882d-e575c34f6191", "type": "concept", "title": "Cameras, license plate readers, drones, geofence warrants, social media monitoring, facial recognition, and cell-site data"}, {"id": "a1fa986b-e0dc-452b-a5c2-faf93fd882d3", "type": "concept", "title": "Data retention, access controls, bias, transparency, and oversight"}, {"id": "ecb0b5c2-fc49-427e-b1d3-a0e4a1ca8da0", "type": "concept", "title": "Community notice and democratic accountability"}], "description": "The gist is to weigh safety against privacy and chilling effects."}, {"id": "fee84587-460e-4be7-8eef-d73928828d86", "type": "subtopic", "title": "Digital evidence", "children": [{"id": "eda53d01-872c-420f-8bfd-162ef314d18f", "type": "concept", "title": "Chain of custody, metadata, authenticity, warrants, encryption, cloud data, and third-party platforms"}, {"id": "dd9685e4-fdb5-43f7-92d9-9943deedb850", "type": "concept", "title": "Overcollection and minimization"}, {"id": "06452531-42fe-4d04-b1fa-5c7dd25b9158", "type": "concept", "title": "Discovery, privacy, and victim-sensitive data"}], "description": "Students learn how evidence integrity changes in digital environments."}]}, {"id": "152d3cd9-a8e9-45e5-b596-f3a103506ce7", "type": "topic", "title": "Bias, Discrimination, Racial Justice, and Equal Protection in Criminal Justice", "description": "Students study how bias and structural inequality affect discretion, enforcement, punishment, legitimacy, and ethical reform obligations.", "children": [{"id": "798e0dea-8970-4891-abc6-b306cdfbd7bb", "type": "subtopic", "title": "Individual and implicit bias", "children": [{"id": "333c8971-10b4-4d21-9102-33ec90fd6658", "type": "concept", "title": "Stereotypes, threat perception, confirmation bias, attribution error, and implicit association"}, {"id": "f2981285-11d8-43b8-ac3d-5b3c029e19ae", "type": "concept", "title": "Training limits and behavioral safeguards"}, {"id": "74a92691-2045-4ab8-8c37-2500bc0b1801", "type": "concept", "title": "Supervision, data review, and accountability"}], "description": "Students learn how bias can shape perception and discretion."}, {"id": "b66696ed-41db-478f-baf0-a01b190e2c34", "type": "subtopic", "title": "Structural inequality", "children": [{"id": "ead6c4fa-a0d7-4fc4-81f2-c0b96d341a4e", "type": "concept", "title": "Racial profiling, neighborhood enforcement patterns, bail, sentencing, school-to-prison pipeline, and collateral consequences"}, {"id": "60527f9c-98a8-45a7-850b-30686fcb58e5", "type": "concept", "title": "Poverty, housing, education, health, and community disinvestment"}, {"id": "2c2ffd3c-07af-49d9-8621-008d5d484e51", "type": "concept", "title": "Disparate impact and cumulative disadvantage"}], "description": "The point is to see how ethical problems can be built into systems."}, {"id": "6810a48f-8485-47ef-943d-c1e9800225cd", "type": "subtopic", "title": "Anti-discrimination practice", "children": [{"id": "3218086f-931c-4e6e-8a74-d51c5a6bd01e", "type": "concept", "title": "Policy revision, bias audits, data transparency, community engagement, and targeted supervision"}, {"id": "2ee08281-d489-4744-87ae-d50de51407f8", "type": "concept", "title": "Civil rights enforcement and equal protection"}, {"id": "8acf0d81-6205-4b14-a341-aea3a09e6c04", "type": "concept", "title": "Measuring reform outcomes ethically"}], "description": "Students practice remedies beyond slogans."}]}, {"id": "50814aa2-8d34-494e-966f-da6b3f09b58f", "type": "topic", "title": "Misconduct, Corruption, Accountability, Internal Affairs, and Whistleblowing", "description": "This module focuses on what happens when professionals violate public trust and how agencies detect, investigate, discipline, prevent, and disclose misconduct.", "children": [{"id": "82577bcd-cd85-4409-a96a-73ee8d88d7e8", "type": "subtopic", "title": "Misconduct types", "children": [{"id": "762de07c-35ba-496f-ac70-0a986e17c376", "type": "concept", "title": "Excessive force, dishonesty, evidence tampering, theft, sexual misconduct, gratuities, bribery, retaliation, and abuse of authority"}, {"id": "1056e5ad-9060-44de-892c-69103fdaebf6", "type": "concept", "title": "On-duty and off-duty conduct"}, {"id": "bae0ba82-f3c9-4b82-8040-9645e937cb65", "type": "concept", "title": "Individual misconduct and organizational tolerance"}], "description": "Students learn to distinguish mistakes, misconduct, corruption, and crime."}, {"id": "8d373f61-9c6f-474e-8578-d77b0c9168fb", "type": "subtopic", "title": "Accountability systems", "children": [{"id": "87483dd0-11ed-49db-bc0e-4f8928aca8f6", "type": "concept", "title": "Complaint intake, classification, interviews, evidence review, findings, discipline, appeal, and public reporting"}, {"id": "659c5bad-620e-46fd-9a88-7cf5d038b6bf", "type": "concept", "title": "Internal affairs, civilian oversight, inspectors general, accreditation, and consent decrees"}, {"id": "21c7514d-de8c-457a-81a9-ea0e1d66a0af", "type": "concept", "title": "Transparency, privacy, union rules, and due process for employees"}], "description": "The gist is to understand how agencies investigate and correct wrongdoing."}, {"id": "d8c77d19-e85a-4d6c-b998-ee51a68af03b", "type": "subtopic", "title": "Whistleblowing", "children": [{"id": "ca297fab-ed40-49f5-a6a7-505650f9d8ac", "type": "concept", "title": "Internal reporting, external reporting, chain of command, retaliation, confidentiality, and public interest disclosures"}, {"id": "b6a6ee68-bd8f-4ef3-84ae-78485009a887", "type": "concept", "title": "Duty of loyalty versus duty to justice"}, {"id": "f1fa8427-802c-4aa6-a11e-5034ef9716b8", "type": "concept", "title": "Documentation, protection, and personal cost"}], "description": "Students learn the ethical risks of speaking up."}]}, {"id": "a7c856e3-47ed-43f2-bad8-356e630c2806", "type": "topic", "title": "Investigative Ethics, Interrogation, Informants, Evidence Integrity, and Forensic Responsibility", "description": "Students learn how truth-seeking can be distorted by pressure, incentives, tunnel vision, coercion, unreliable evidence, or weak scientific practice.", "children": [{"id": "31964e7d-f724-4243-abc9-f7c48f901ce3", "type": "subtopic", "title": "Interrogation and confession ethics", "children": [{"id": "8e24c4a3-c154-4315-8142-b2f858286dc9", "type": "concept", "title": "Miranda, voluntariness, deception, length, youth, disability, mental illness, and trauma"}, {"id": "9fa1c145-9c9b-4f57-b9ec-9ac43ffefca0", "type": "concept", "title": "Recording, rapport-based interviewing, and coercion safeguards"}, {"id": "414b25ea-90b8-4382-a549-6a4332553fc3", "type": "concept", "title": "Confession contamination and corroboration"}], "description": "Students learn how pressure can create false or unreliable evidence."}, {"id": "d377a668-57b5-4402-8fdb-965a90b4e49d", "type": "subtopic", "title": "Informants and undercover work", "children": [{"id": "7e3931f1-3927-498c-9965-003085bc7365", "type": "concept", "title": "Confidential informants, jailhouse informants, paid witnesses, undercover operations, and entrapment"}, {"id": "d4d315b3-121c-4dcb-a743-cb5aa4e93f22", "type": "concept", "title": "Reliability, corroboration, safety, disclosure, and exploitation concerns"}, {"id": "d645fda9-fcb4-4ed8-a323-6c55d9c611b3", "type": "concept", "title": "Documentation and supervisory review"}], "description": "The point is to manage deception and incentives ethically."}, {"id": "94c05c2b-077b-42d7-9355-0b4851f5c2fb", "type": "subtopic", "title": "Forensic integrity", "children": [{"id": "65be5c1e-1c96-4db3-80e6-0f5d9c355e61", "type": "concept", "title": "Evidence collection, chain of custody, lab independence, cognitive bias, validation, error rates, and expert testimony"}, {"id": "676dc15d-c943-44f0-a9d9-9cc04f68a98c", "type": "concept", "title": "Forensic disciplines with contested reliability"}, {"id": "d6504458-33a7-4ea4-9926-90449cde0f26", "type": "concept", "title": "Brady/Giglio, disclosure, and correcting errors"}], "description": "Students examine scientific and professional duties."}]}, {"id": "8e5e23f9-252d-4d65-b2de-da7c8ee833f5", "type": "topic", "title": "Prosecutorial Ethics: Charging, Plea Bargaining, Disclosure, Victims, and Minister-of-Justice Duties", "description": "This topic explores the special ethical burden of prosecutors, whose duty is not merely to win but to seek justice.", "children": [{"id": "308aeb84-c799-4d6e-b8e6-c69030d1403f", "type": "subtopic", "title": "Charging discretion", "children": [{"id": "35932465-ef1e-4d23-bb3e-b9c79a9b0730", "type": "concept", "title": "Probable cause, evidentiary sufficiency, public interest, overcharging, diversion, and declination"}, {"id": "b109d832-5d9d-4f70-9275-901779338704", "type": "concept", "title": "Race, poverty, media pressure, and political incentives"}, {"id": "466cadd5-6d5e-44ee-9e1f-ab2a02cc0137", "type": "concept", "title": "Transparency and consistency"}], "description": "Students learn the prosecutor's power to define the case."}, {"id": "cc59837e-7fcb-4382-b814-3afda35d9a40", "type": "subtopic", "title": "Plea bargaining", "children": [{"id": "57888d35-c983-4a44-9b8e-5361a30ad6cc", "type": "concept", "title": "Charge bargaining, sentence bargaining, trial penalty, coercion, innocence risk, and collateral consequences"}, {"id": "9d2e4c63-6ef7-40c3-8776-7723062d8470", "type": "concept", "title": "Victim input, defense capacity, and court oversight"}, {"id": "8402efaa-d7bb-4c52-adc1-ea5595baeceb", "type": "concept", "title": "Plea records and accountability"}], "description": "The gist is to evaluate the ethics of negotiated justice."}, {"id": "26a0a654-9753-4cac-802f-b53b185be203", "type": "subtopic", "title": "Disclosure and candor", "children": [{"id": "a7b32c6e-02f1-4760-8a15-9b53cd118e59", "type": "concept", "title": "Brady, Giglio, exculpatory evidence, impeachment evidence, open-file discovery, and late disclosure"}, {"id": "e819371b-26f6-4e31-860a-42bf7fa922b9", "type": "concept", "title": "Wrongful conviction, conviction integrity units, and post-conviction duties"}, {"id": "0dd79ad7-21f2-412a-99d6-fcdc5ef286e7", "type": "concept", "title": "Victim communication and public statements"}], "description": "Students study the duty to disclose and correct injustice."}]}, {"id": "dde5c98d-1f14-4d30-8bad-ee6d4cdac412", "type": "topic", "title": "Defense Ethics, Client Loyalty, Confidentiality, Competence, and Access to Counsel", "description": "Students study the defense role in an adversarial system, including zealous advocacy, client autonomy, conflicts, truth, and indigent-defense constraints.", "children": [{"id": "ca0134c3-85fe-4644-988d-b54ca9792c49", "type": "subtopic", "title": "Defense role", "children": [{"id": "b4a538cf-48c5-423f-a563-526742cdf4f3", "type": "concept", "title": "Presumption of innocence, burden of proof, adversarial testing, and dignity"}, {"id": "5d073287-5e11-4dd1-8f93-71e25a365e99", "type": "concept", "title": "Zealous advocacy, client autonomy, and professional boundaries"}, {"id": "c3bcbee7-2b69-477d-be20-dff53fb71474", "type": "concept", "title": "Public defense and private defense constraints"}], "description": "Students understand why defending accused people is an ethical public function."}, {"id": "4808fd5a-1201-49d4-b255-3a0c1be87217", "type": "subtopic", "title": "Confidentiality and conflicts", "children": [{"id": "ee3467fb-86e8-48f9-b3cd-8cd35cee334e", "type": "concept", "title": "Attorney-client privilege, confidentiality, conflicts of interest, withdrawal, and perjury dilemmas"}, {"id": "dc9b0dc5-861c-46fe-a0f0-f61fed03142a", "type": "concept", "title": "Representing unpopular clients"}, {"id": "509a0cdc-d22c-43fb-a912-ef8347653af9", "type": "concept", "title": "Media, family members, and third-party payors"}], "description": "The point is to navigate duties to client, court, and justice."}, {"id": "85ceec6b-65a2-4b6d-a218-79978a36bc2a", "type": "subtopic", "title": "Access to counsel", "children": [{"id": "e2efc14c-fddd-45ec-8366-edb83a10fa54", "type": "concept", "title": "Caseloads, funding, investigation, expert access, plea pressure, and competence"}, {"id": "3a2dfa0b-0832-45c9-9616-b55e50dfaf6c", "type": "concept", "title": "Misdemeanor justice and pretrial detention"}, {"id": "a2a0d465-81d7-45ee-afd3-08d61b78e671", "type": "concept", "title": "Structural reform and professional responsibility"}], "description": "Students analyze systemic ethics in indigent defense."}]}, {"id": "e9b273ef-f6cc-4a1c-aed2-3ad74a65b7e4", "type": "topic", "title": "Judicial, Courtroom, and Pretrial Ethics: Bail, Pleas, Sentencing, and Due Process", "description": "This module examines ethical problems in courts, including neutrality, coercion, delay, plea pressure, bail, expert testimony, and courtroom professionalism.", "children": [{"id": "02b96490-28e7-49c4-a99d-15c98bee69a0", "type": "subtopic", "title": "Judicial neutrality", "children": [{"id": "06c929c3-c035-4e98-96bd-8ecf4f2b6c50", "type": "concept", "title": "Impartiality, conflicts, recusal, demeanor, ex parte communication, delay, and public confidence"}, {"id": "ace9daa4-50a9-4d3c-926b-c59166eb3a95", "type": "concept", "title": "Courtroom control and respectful treatment"}, {"id": "d785f246-188b-4d79-ae05-93c8d90f8f91", "type": "concept", "title": "Implicit bias and decision review"}], "description": "Students learn the ethical demands of adjudication."}, {"id": "4d64ba9a-b5af-4977-8a70-f51b180dd347", "type": "subtopic", "title": "Pretrial justice", "children": [{"id": "ce48dfa4-14f5-4470-8843-736bda841332", "type": "concept", "title": "Bail, preventive detention, risk assessment, ability to pay, supervision, and speedy trial"}, {"id": "53a5d2d7-d744-469b-9d74-8f34c84db75f", "type": "concept", "title": "Public safety, presumption of innocence, and coercive plea pressure"}, {"id": "e055bd9e-b0fa-48b7-8023-531ed4e6a6b1", "type": "concept", "title": "Jail harm and case outcomes"}], "description": "The gist is to evaluate liberty decisions before conviction."}, {"id": "0a7b8b41-b8cb-4ebd-a090-78b5e8e34e53", "type": "subtopic", "title": "Sentencing ethics", "children": [{"id": "2177e80a-2fe8-4f95-86f5-7aefbce1de88", "type": "concept", "title": "Guidelines, mandatory minimums, mitigation, victim impact, proportionality, disparity, and collateral consequences"}, {"id": "e3fbce6e-ad5b-4d5c-91fa-dcc86af35128", "type": "concept", "title": "Transparency and reasons for sentence"}, {"id": "d43558c5-6a02-444f-8f4c-fb6b439ccf33", "type": "concept", "title": "Problem-solving courts and treatment mandates"}], "description": "Students connect court discretion to punishment consequences."}]}, {"id": "864df360-75c2-4fc6-b385-2cf1e1e16ff1", "type": "topic", "title": "Correctional Ethics: Custody, Safety, Health, Solitary Confinement, and Human Dignity", "description": "Students analyze ethical obligations in jails, prisons, probation, parole, reentry, and community supervision, where state control shapes daily life.", "children": [{"id": "92ea2376-9f9e-42b9-b2e8-1f52b46a7aa8", "type": "subtopic", "title": "Custodial power", "children": [{"id": "e64528fd-737c-4b38-ae77-0aa03523b425", "type": "concept", "title": "Safety, dignity, food, sanitation, medical care, mental health, disability accommodation, and religious rights"}, {"id": "8f41846f-b848-4518-886b-e5f99bfbdfaf", "type": "concept", "title": "Staff safety and incarcerated people's rights"}, {"id": "d234d8a4-edae-409a-a56a-7a4f7b22b494", "type": "concept", "title": "Public invisibility and accountability gaps"}], "description": "Students learn ethical duties toward people the state confines."}, {"id": "3e03909a-4e9d-48f5-b0b0-44d285a9edce", "type": "subtopic", "title": "Conditions and discipline", "children": [{"id": "ce1de225-c578-4001-b321-a18f4833b1a6", "type": "concept", "title": "Segregation, solitary confinement, restraints, searches, discipline, grievance systems, and use of force in facilities"}, {"id": "76a87ca0-68d0-41df-8ef9-eff42047ab21", "type": "concept", "title": "Contraband control and privacy"}, {"id": "8defe801-ac0c-414e-94e8-65bacb86e577", "type": "concept", "title": "Women, LGBTQ people, youth, older adults, and people with disabilities"}], "description": "The point is to evaluate restrictions inside custody."}, {"id": "14d78782-a0cc-4926-90fa-a7e7cce9ce66", "type": "subtopic", "title": "Reentry and supervision", "children": [{"id": "f5ee28f4-d1ef-4b1b-8fe3-8425ba9b902c", "type": "concept", "title": "Probation, parole, technical violations, electronic monitoring, fees, housing, employment, treatment, and family reunification"}, {"id": "9c8a4ef0-add4-494b-8b45-95d747e48ba8", "type": "concept", "title": "Rehabilitation and reintegration"}, {"id": "f6274701-6282-42ad-8e14-37a77328efa3", "type": "concept", "title": "Desistance, dignity, and public safety"}], "description": "Students connect corrections ethics to community life."}]}, {"id": "4d202d9f-7b81-4187-95db-46a9c0792dd8", "type": "topic", "title": "Ethics of Punishment: Retribution, Deterrence, Rehabilitation, Incapacitation, Mercy, and Restoration", "description": "This topic asks what punishment is for, when it is justified, and how sentencing, parole, reentry, and restorative justice reflect competing moral theories.", "children": [{"id": "9d873152-da6e-4909-84ba-24dc58d6d930", "type": "subtopic", "title": "Punishment theories", "children": [{"id": "3d2a0173-81f1-48a9-af63-142b38b8e655", "type": "concept", "title": "Retribution, deterrence, incapacitation, rehabilitation, restoration, denunciation, and mercy"}, {"id": "9eda5e4c-c9db-498e-bf49-fca2a55281a0", "type": "concept", "title": "Proportionality and desert"}, {"id": "8a31cc0e-afeb-45c9-93ee-8bd354dc432f", "type": "concept", "title": "When theories conflict in real cases"}], "description": "Students learn the moral justifications for state punishment."}, {"id": "6b63efb6-75c2-4c80-8861-622ec27a7eba", "type": "subtopic", "title": "Sentencing policy", "children": [{"id": "b957bca2-ba0f-4ea7-a936-354b0b98d6b9", "type": "concept", "title": "Mandatory minimums, three-strikes laws, sentencing guidelines, parole, life without parole, fines, fees, and collateral consequences"}, {"id": "6f187ae0-655b-4ac4-9899-686f3c27c588", "type": "concept", "title": "Mass incarceration and racial disparity"}, {"id": "7c08d4df-f303-45f0-b8d8-52632221c2b5", "type": "concept", "title": "Cost, effectiveness, and humanity"}], "description": "The gist is to assess punishment at scale."}, {"id": "eaeb768c-3f52-413a-9ad2-2b31f138c29f", "type": "subtopic", "title": "Restorative and transformative justice", "children": [{"id": "17cda0ae-4689-4ee5-a136-c08c6393d0e0", "type": "concept", "title": "Victim-offender dialogue, community accountability, repair, restitution, circles, and conferencing"}, {"id": "e4654fd9-feaf-4d76-ab39-a333a2b9b2c0", "type": "concept", "title": "Limits, coercion risks, and serious-violence cases"}, {"id": "ed8f17b5-cc13-4978-b4d0-2cf51422f5da", "type": "concept", "title": "Community safety beyond incarceration"}], "description": "Students consider alternatives to conventional punishment."}]}, {"id": "41101628-f523-4cbd-9ca1-ec796cd27c36", "type": "topic", "title": "Victims, Communities, Juveniles, Trauma, and Restorative Justice", "description": "Students learn to account for people and communities harmed by crime and punishment while avoiding simplistic victim/offender categories.", "children": [{"id": "c54ad500-e449-4f17-a7c5-7efc7bda7844", "type": "subtopic", "title": "Victim ethics", "children": [{"id": "8c5860e5-65e6-4a06-93e6-7a7b10974e37", "type": "concept", "title": "Respect, privacy, safety, notification, participation, compensation, and avoiding retraumatization"}, {"id": "863af2e7-4389-4726-921e-f3dcd567c7b4", "type": "concept", "title": "Victim impact statements and prosecutor communication"}, {"id": "5487cc66-25d5-4614-8c72-fff42367ee41", "type": "concept", "title": "Media, confidentiality, and dignity"}], "description": "Students learn duties to people harmed by crime."}, {"id": "ca428518-7265-4656-8f7c-82c059982b11", "type": "subtopic", "title": "Community harm", "children": [{"id": "043535b0-6a20-4316-8a5c-f044189b898e", "type": "concept", "title": "Community policing, collective efficacy, neighborhood trauma, violence interruption, and legitimacy"}, {"id": "c68ca3b1-d9a2-4357-995f-b9e191a004d5", "type": "concept", "title": "Over-policing, under-protection, and community distrust"}, {"id": "9c970602-54b3-4c44-9541-1544a8d6f378", "type": "concept", "title": "Listening, participation, and co-production of safety"}], "description": "The point is to see criminal justice as relational and public."}, {"id": "7d850dbb-1056-4438-a9d6-287c467ddc8f", "type": "subtopic", "title": "Youth justice", "children": [{"id": "101c76fe-555a-4045-83f2-e012e00b2ce5", "type": "concept", "title": "Juvenile culpability, diversion, transfer to adult court, detention, school policing, and family involvement"}, {"id": "f4fe704a-3e63-4b69-bd19-00f57f56f2d9", "type": "concept", "title": "Brain development, trauma, and rehabilitation"}, {"id": "69c1aa81-3522-481c-9932-06b573fa4d0f", "type": "concept", "title": "Racial disparity and school-to-prison pipeline"}], "description": "Students apply developmental and rights-based ethics."}]}, {"id": "6ecb111f-e193-43bf-b7c1-dea7f6847868", "type": "topic", "title": "Research Ethics, Data Ethics, Algorithmic Risk, AI, and Evidence-Based Reform", "description": "This module covers the ethics of studying, measuring, predicting, and reforming criminal justice through data, evaluation, algorithms, and technology.", "children": [{"id": "1e3d2f0b-2504-4669-a8b1-7d072e7064d7", "type": "subtopic", "title": "Human subjects and research ethics", "children": [{"id": "3e20b82e-8da1-4256-9536-03c155c881a9", "type": "concept", "title": "IRB, informed consent, confidentiality, coercion, prisoner research, vulnerable populations, and community-based research"}, {"id": "51b1dfef-ce85-42f9-99dc-bedfea4ef277", "type": "concept", "title": "Program evaluation and evidence ratings"}, {"id": "ad68b3df-b2e7-47c4-aeef-f2b8180d4fda", "type": "concept", "title": "Publishing results honestly and avoiding harm"}], "description": "Students learn the duties of studying justice-involved people."}, {"id": "6bbb86e1-8db3-4508-a2f8-da388006e9b9", "type": "subtopic", "title": "Data ethics", "children": [{"id": "6dde055c-708a-48be-a9d4-d475908c9b8b", "type": "concept", "title": "Official statistics, missing data, data quality, privacy, de-identification, data sharing, and misuse"}, {"id": "e5276af2-acc9-446b-8a0e-b999c31a06d1", "type": "concept", "title": "Crime data, arrest data, victimization data, corrections data, and court data"}, {"id": "588ee666-6545-4246-bc02-dc5206bd8066", "type": "concept", "title": "Transparency, reproducibility, and equity in measurement"}], "description": "The gist is to handle justice data responsibly."}, {"id": "b289fc15-cc29-44be-8ed1-97b415e4c0d7", "type": "subtopic", "title": "Algorithms and AI", "children": [{"id": "23357917-541b-43b4-b1ac-2e173c02fd15", "type": "concept", "title": "Predictive policing, risk assessment, facial recognition, gunshot detection, social media analysis, and generative AI"}, {"id": "c0b4744c-588c-41d9-978b-da3f86dc7352", "type": "concept", "title": "Bias, explainability, validation, due process, appeal, and accountability"}, {"id": "4256b8cf-be73-4770-8cf7-f25e1efef04d", "type": "concept", "title": "Procurement, auditing, community oversight, and moratoria"}], "description": "Students analyze high-stakes automated tools."}]}, {"id": "3a6134e9-9040-4406-aabb-196c3d5b6c1c", "type": "topic", "title": "Professional Identity Capstone: Ethical Leadership, Scenario Simulation, and Reflective Practice", "description": "Students synthesize the course by applying ethical frameworks to realistic dilemmas and building a professional code for responsible criminal justice practice.", "children": [{"id": "afe82a67-a45f-441b-a747-696c5343af2d", "type": "subtopic", "title": "Ethical leadership", "children": [{"id": "4a94918b-e15a-4643-a1d0-82d216c8c059", "type": "concept", "title": "Recruitment, training, supervision, discipline, wellness, peer norms, and leadership modeling"}, {"id": "47b30c3d-8571-41ce-ad9f-1eddd48168f8", "type": "concept", "title": "Moral courage, humility, accountability, and service"}, {"id": "d5dedee8-9ea8-4931-afff-7fe68b5af301", "type": "concept", "title": "Policy versus practice gaps"}], "description": "Students learn how culture shapes conduct."}, {"id": "085b228d-aca7-4c6b-b5d7-f176cde0fc05", "type": "subtopic", "title": "Scenario simulation", "children": [{"id": "a009871f-ad2a-44f4-ad57-021df060928e", "type": "concept", "title": "Use-of-force dilemma, Brady disclosure, informant reliability, correctional discipline, surveillance proposal, and whistleblowing scenario"}, {"id": "25e7e0bb-b5e8-4b48-8bd3-fc1c5a073fce", "type": "concept", "title": "Stakeholder mapping, options, harms, legal constraints, and ethical justification"}, {"id": "cdead010-5104-4edc-9ee6-834e9092da05", "type": "concept", "title": "Decision memo and oral defense"}], "description": "The point is to practice judgment before real stakes arrive."}, {"id": "f9dc87fc-e324-40ad-aaa0-e5544d356df7", "type": "subtopic", "title": "Reflective practice", "children": [{"id": "2cae9758-50b8-40f9-9049-c1fac8816816", "type": "concept", "title": "Personal values versus professional duties"}, {"id": "df4bab60-80e7-4dbe-9456-3cb285bbc65c", "type": "concept", "title": "Bias awareness, boundaries, stress, burnout, and moral injury"}, {"id": "e247e4f1-5715-451f-ace5-22d1ecdf5802", "type": "concept", "title": "Lifelong learning and accountability plan"}], "description": "Students build a durable professional code."}]}], "dbBacked": true}$ecjjson$::jsonb,
