  ('33a23b0e-aefe-4d55-9581-2d88921a8dde', 'd7e8f9a0-1b2c-4e37-8f67-8a9b0c1d2e77', '19671742-5b0e-46d7-8849-a897c0575468', 'subtopic'::public.curated_course_node_type, 'Ethical theories', 'Students learn frameworks for disciplined moral reasoning.', 0),
